{-# LANGUAGE LambdaCase #-}
{-# LANGUAGE RecordWildCards #-}

-- | ICal Recurrence
--
-- This module exists to help you canculate the recurrence set of a component.
--
-- [section 3.8.5](https://datatracker.ietf.org/doc/html/rfc5545#section-3.8.5)
--
-- @
-- The following properties specify recurrence information in calendar
-- components.
-- @
--
-- [section 3.8.5.1](https://datatracker.ietf.org/doc/html/rfc5545#section-3.8.5.1)
--
-- @
-- The recurrence set is the complete
-- set of recurrence instances for a calendar component.  The
-- recurrence set is generated by considering the initial "DTSTART"
-- property along with the "RRULE", "RDATE", and "EXDATE" properties
-- contained within the recurring component.
-- [...]
-- The final recurrence set is generated by gathering all of the
-- start DATE-TIME values generated by any of the specified "RRULE"
-- and "RDATE" properties, and then excluding any start DATE-TIME
-- values specified by "EXDATE" properties.
-- @
--
-- However, because recurrence sets can be infinite, we do not reify them
-- entirely and instead provide only functions that produce finite results.
--
--
-- This module is quite big and that's on purpose.
-- The problem is the following cyclical dependencies:
--
-- expandRecurrence -> resolveEndOrDurationDate
-- resolveEndOrDurationDate -> resolveLocalTime
-- resolveLocalTime -> expandRecurrence
module ICal.Recurrence
  ( module ICal.Recurrence,
    module ICal.Recurrence.RecurrenceRule,
    module ICal.Recurrence.Types,
  )
where

import Conformance
import Control.Applicative
import Control.Monad
import Control.Monad.Reader
import Data.Bifunctor (first)
import Data.List.NonEmpty (NonEmpty (..))
import qualified Data.List.NonEmpty as NE
import Data.Map.Strict (Map)
import qualified Data.Map.Strict as M
import Data.Maybe
import Data.Set (Set)
import qualified Data.Set as S
import qualified Data.Time as Time
import ICal
import ICal.PropertyType.DateTimes as DateTimes
import ICal.Recurrence.RecurrenceRule
import ICal.Recurrence.Types

-- | Everything in a calendar that recurs
--
-- Components sharing a UID form one recurrence set.
--
-- @
-- The full range of calendar components specified by a
-- recurrence set is referenced by referring to just the "UID"
-- property value corresponding to the calendar component.  The
-- "RECURRENCE-ID" property allows the reference to an individual
-- instance within the recurrence set.
-- @
--
-- This stays in 'R' rather than running the time zone context itself, so that
-- a caller can go on resolving without rebuilding those contexts.  See
-- 'runCalendarR'.
recurCalendar :: Time.Day -> Calendar -> R CalendarRecurrence
recurCalendar limit cal = do
  calendarRecurrenceEvents <- recurEvents limit (calendarEvents cal)
  calendarRecurrenceTodos <- recurTodos limit (calendarTodos cal)
  calendarRecurrenceJournals <- recurJournals limit (calendarJournals cal)
  pure CalendarRecurrence {..}

-- | Run an 'R' action with the time zones a calendar defines
runCalendarR :: Time.Day -> Calendar -> R a -> Resolv a
runCalendarR limit cal = runR limit (calendarTimeZoneMap cal)

-- | The recurrence sets of the VEVENTs of a calendar
recurEvents :: Time.Day -> [Event] -> R (Map UID (Set (Occurrence Event)))
recurEvents limit = recur limit . map eventRecurring

-- | The recurrence sets of the VTODOs of a calendar
recurTodos :: Time.Day -> [Todo] -> R (Map UID (Set (Occurrence Todo)))
recurTodos limit = recur limit . map todoRecurring

-- | The recurrence sets of the VJOURNALs of a calendar
recurJournals :: Time.Day -> [Journal] -> R (Map UID (Set (Occurrence Journal)))
recurJournals limit = recur limit . map journalRecurring

-- | The recurrence sets of a collection of components, by UID
--
-- This groups by UID itself, which is why it takes a collection rather than a
-- single component: the occurrences of one component depend on the others
-- sharing its UID.
recur ::
  (Ord component) =>
  Time.Day ->
  [Recurring component] ->
  R (Map UID (Set (Occurrence component)))
recur limit = traverse (recurGroup limit) . groupByUID

-- | The components sharing one UID, gathered
groupByUID :: [Recurring component] -> Map UID (NonEmpty (Recurring component))
groupByUID =
  M.fromListWith (<>) . map (\recurring -> (recurringUID recurring, recurring :| []))

-- | The recurrence set of one UID's components
--
-- The component without a RECURRENCE-ID is the series, and each component with
-- one replaces the instance it names.
--
-- @
-- The DATE-TIME value is set to the time when the original
-- recurrence instance would occur; meaning that if the intent is to
-- change a Friday meeting to Thursday, the DATE-TIME is still set to
-- the original Friday meeting.
-- @
--
-- So a component with a RECURRENCE-ID does not add a Thursday to a recurrence
-- set that still holds its Friday.  It says the Friday instance is now on
-- Thursday.
recurGroup ::
  (Ord component) =>
  Time.Day ->
  NonEmpty (Recurring component) ->
  R (Set (Occurrence component))
recurGroup limit group = do
  let uid = recurringUID (NE.head group)
  let series = NE.filter (isNothing . recurringRecurrenceIdentifier) group
  -- One UID names one recurrence set, so two components that both leave out
  -- the RECURRENCE-ID do not say which of them the overrides are overriding.
  -- The spec does not define this case, and dropping one would discard what
  -- the calendar said, so both series are expanded.
  when (length series > 1) $ emitFixableErrorR $ RecurrenceMultipleSeries uid
  seriesOccurrences <- S.unions <$> mapM (expandRecurring limit) series
  overriding <- winningOverrides uid (NE.toList group)
  let seriesStarts = S.fromList $ mapMaybe occurrenceStart $ S.toList seriesOccurrences
  -- An override that names no instance the series generates.  The spec says
  -- nothing about this, and dropping the override would lose what the calendar
  -- said, so it contributes its own instance and the calendar is reported as
  -- needing a fix.
  forM_ (M.keys overriding) $ \start ->
    unless (start `S.member` seriesStarts) $
      emitFixableErrorR $
        RecurrenceIdentifierUnmatched uid start
  let notOverridden =
        S.filter (maybe True (not . (`M.member` overriding)) . occurrenceStart) seriesOccurrences
  pure $ notOverridden <> S.fromList (map recurringOccurrence (M.elems overriding))

-- | The component that overrides each instance that has one
--
-- Two components of one UID with the same RECURRENCE-ID are two revisions of
-- the same instance.
--
-- @
-- When a calendar component is created, its sequence
-- number is 0.  It is monotonically incremented by the "Organizer's"
-- CUA each time the "Organizer" makes a significant revision to the
-- calendar component.
-- @
--
-- so the higher SEQUENCE is the later revision and wins.  Two revisions
-- sharing a SEQUENCE contradict that, and the calendar does not say which to
-- take, so 'Ord' settles it rather than the order the components happen to
-- appear in the file.
winningOverrides ::
  (Ord component) =>
  UID ->
  [Recurring component] ->
  R (Map DateTimeStart (Recurring component))
winningOverrides uid components =
  let candidates =
        M.fromListWith (<>) $
          mapMaybe
            ( \recurring -> do
                identifier <- recurringRecurrenceIdentifier recurring
                pure (recurrenceIdentifierDateTimeStart identifier, recurring :| [])
            )
            components
   in flip M.traverseWithKey candidates $ \start these -> do
        let winner =
              snd $ maximum $ NE.map (\recurring -> (recurringSequenceNumber recurring, recurring)) these
        let tied =
              NE.filter
                ( \recurring ->
                    recurring /= winner
                      && recurringSequenceNumber recurring == recurringSequenceNumber winner
                )
                these
        unless (null tied) $ emitFixableErrorR $ RecurrenceIdentifierDuplicate uid start
        pure winner

-- | The instance that a RECURRENCE-ID names
--
-- @
-- The property value is the original value of the "DTSTART" property
-- of the recurrence instance.
-- @
--
-- @
-- This property MUST have the same
-- value type as the "DTSTART" property contained within the
-- recurring component.  Furthermore, this property MUST be specified
-- as a date with local time if and only if the "DTSTART" property
-- contained within the recurring component is specified as a date
-- with local time.
-- @
--
-- So the value can be compared with a generated instance's start as written,
-- and a RECURRENCE-ID that matches none of them exactly is non-conforming
-- input rather than a near miss to be resolved.  The RANGE parameter is not
-- part of the value.
recurrenceIdentifierDateTimeStart :: RecurrenceIdentifier -> DateTimeStart
recurrenceIdentifierDateTimeStart = \case
  RecurrenceIdentifierDate _ date -> DateTimeStartDate date
  RecurrenceIdentifierDateTime _ dateTime -> DateTimeStartDateTime dateTime

-- | The recurrence-relevant properties of a VEVENT
eventRecurring :: Event -> Recurring Event
eventRecurring event =
  Recurring
    { recurringComponent = event,
      recurringUID = eventUID event,
      recurringSequenceNumber = eventSequenceNumber event,
      recurringRecurrenceIdentifier = eventRecurrenceIdentifier event,
      recurringStart = eventDateTimeStart event,
      recurringEnd = first dateTimeEndRecurrenceEnd <$> eventDateTimeEndDuration event,
      recurringRecurrence =
        Recurrence
          { recurrenceExceptionDateTimes = eventExceptionDateTimes event,
            recurrenceRecurrenceDateTimes = eventRecurrenceDateTimes event,
            recurrenceRecurrenceRules = eventRecurrenceRules event
          }
    }

-- | The recurrence-relevant properties of a VTODO
todoRecurring :: Todo -> Recurring Todo
todoRecurring todo =
  Recurring
    { recurringComponent = todo,
      recurringUID = todoUID todo,
      recurringSequenceNumber = todoSequenceNumber todo,
      recurringRecurrenceIdentifier = todoRecurrenceIdentifier todo,
      recurringStart = todoDateTimeStart todo,
      recurringEnd = first dateTimeDueRecurrenceEnd <$> todoDateTimeDueDuration todo,
      recurringRecurrence =
        Recurrence
          { recurrenceExceptionDateTimes = todoExceptionDateTimes todo,
            recurrenceRecurrenceDateTimes = todoRecurrenceDateTimes todo,
            recurrenceRecurrenceRules = todoRecurrenceRules todo
          }
    }

-- | The recurrence-relevant properties of a VJOURNAL
--
-- A VJOURNAL has no property for the end of an instance, so its occurrences
-- never have one either.
journalRecurring :: Journal -> Recurring Journal
journalRecurring journal =
  Recurring
    { recurringComponent = journal,
      recurringUID = journalUID journal,
      recurringSequenceNumber = journalSequenceNumber journal,
      recurringRecurrenceIdentifier = journalRecurrenceIdentifier journal,
      recurringStart = journalDateTimeStart journal,
      recurringEnd = Nothing,
      recurringRecurrence =
        Recurrence
          { recurrenceExceptionDateTimes = journalExceptionDateTimes journal,
            recurrenceRecurrenceDateTimes = journalRecurrenceDateTimes journal,
            recurrenceRecurrenceRules = journalRecurrenceRules journal
          }
    }

-- | Expand one component's own DTSTART, RRULE, RDATE and EXDATE
--
-- This is one component's own recurrence, not the recurrence set of its UID:
-- it knows nothing about the components that override its instances.
expandRecurring ::
  (Ord component) =>
  Time.Day ->
  Recurring component ->
  R (Set (Occurrence component))
expandRecurring limit recurring =
  expandRecurrence limit (recurringRecurrence recurring) (recurringOccurrence recurring)

-- | The instance that a component's own DTSTART names
recurringOccurrence :: Recurring component -> Occurrence component
recurringOccurrence recurring =
  Occurrence
    { occurrenceComponent = recurringComponent recurring,
      occurrenceStart = recurringStart recurring,
      occurrenceEnd = recurringEnd recurring
    }

-- | Compute the recurrence set, expanding the recurrence rules as far as a
-- given limit
--
-- A recurrence rule can be infinite, so it is only expanded as far as the
-- limit.  Nothing else is bounded by it.  DTSTART and the instances that the
-- RDATEs enumerate are finite however far out they fall, and leaving them out
-- would discard what the calendar actually said, so they are returned whether
-- or not they lie beyond the limit.
--
-- The occurrence given is the one that DTSTART names, and every occurrence
-- produced carries its component.
expandRecurrence ::
  (Ord component) =>
  Time.Day ->
  Recurrence ->
  Occurrence component ->
  R (Set (Occurrence component))
expandRecurrence limit Recurrence {..} startOccurrence =
  -- @
  -- The "DTSTART" property for a "VEVENT" specifies the inclusive
  -- start of the event.  For recurring events, it also specifies the
  -- very first instance in the recurrence set.
  -- @
  -- @
  -- The "DTSTART" property
  -- defines the first instance in the recurrence set.
  -- @
  case occurrenceStart startOccurrence of
    Nothing -> pure $ S.singleton startOccurrence
    Just startDateTime -> do
      let endOrDuration = occurrenceEnd startOccurrence
      let component = occurrenceComponent startOccurrence
      occurrencesFromRecurrenceDateTimes <- recurRecurrenceDateTimes component startDateTime endOrDuration recurrenceRecurrenceDateTimes
      occurrencesFromRecurrenceRules <- recurRecurrenceRules component limit startDateTime endOrDuration recurrenceRecurrenceRules
      -- @
      -- The final recurrence set is generated by gathering all of the
      -- start DATE-TIME values generated by any of the specified "RRULE"
      -- and "RDATE" properties, and then excluding any start DATE-TIME
      -- values specified by "EXDATE" properties.
      -- @
      -- @
      -- Where duplicate instances are generated by the "RRULE"
      -- and "RDATE" properties, only one recurrence is considered.
      -- Duplicate instances are ignored.
      -- @
      -- @
      -- The
      -- duration of a specific recurrence may be modified in an exception
      -- component or simply by using an "RDATE" property of PERIOD value
      -- type.
      -- @
      --
      -- The recurrence set is a set of instances, so two of them must not
      -- share a start.  Keying on the whole occurrence would not do it,
      -- because the same start can arrive with two different ends: a
      -- period-valued RDATE is exactly how the duration of one instance is
      -- changed, so it is meant to collide with the instance the rule
      -- generates.
      --
      -- Which one survives is settled by the quote above.  An RDATE that
      -- names the same start as the rule is the one carrying the modified
      -- duration, so it wins.  DTSTART beats the rule as well, because its
      -- end is stated outright while the rule's is derived from it.
      --
      -- 'M.fromList' keeps the last value for a key, so these are listed
      -- in increasing order of precedence.
      let preliminarySet =
            S.fromList $
              M.elems $
                M.fromList $
                  map (\occurrence -> (occurrenceStart occurrence, occurrence)) $
                    concat
                      [ S.toList occurrencesFromRecurrenceRules,
                        [startOccurrence],
                        S.toList occurrencesFromRecurrenceDateTimes
                      ]
      removeExceptionDatetimesSet recurrenceExceptionDateTimes preliminarySet

-- | Compute the occurrences that the recurrence rules imply
recurRecurrenceRules ::
  (Ord component) =>
  component ->
  -- | Limit
  Time.Day ->
  DateTimeStart ->
  Maybe (Either RecurrenceEnd Duration) ->
  Set RecurrenceRule ->
  R (Set (Occurrence component))
recurRecurrenceRules component limit start mEndOrDuration recurrenceRules = do
  case S.toList recurrenceRules of
    [] -> pure S.empty
    [recurrenceRule] -> recurRecurrenceRule component limit start mEndOrDuration recurrenceRule
    l -> do
      -- The spec says:
      --
      -- @
      -- The recurrence set generated with multiple "RRULE" properties is
      -- undefined.
      -- @
      --
      -- However, we choose to define it as the union of the
      -- reccurence sets defined by the recurrence rules.
      emitFixableErrorR $ RecurrenceMultipleRecurrenceRules recurrenceRules
      S.unions <$> mapM (recurRecurrenceRule component limit start mEndOrDuration) l

recurRecurrenceRule ::
  (Ord component) =>
  component ->
  -- | Limit
  Time.Day ->
  DateTimeStart ->
  Maybe (Either RecurrenceEnd Duration) ->
  RecurrenceRule ->
  R (Set (Occurrence component))
recurRecurrenceRule component limit start mEndOrDuration recurrenceRule = do
  localisedRule <- localiseUntil start recurrenceRule
  exists <- localTimeExists start
  generatedStarts <- recurRecurrenceRuleDateTimeStarts exists limit start localisedRule
  starts <- boundByUntil start recurrenceRule generatedStarts
  fmap S.fromList $
    forM (S.toList starts) $ \newStart -> do
      newMEndOrDuration <- resolveEndOrDurationDate start mEndOrDuration newStart
      pure
        Occurrence
          { occurrenceComponent = component,
            occurrenceStart = Just newStart,
            occurrenceEnd = newMEndOrDuration
          }

-- | Express a UTC 'Until' in the local time of the time zone of 'DateTimeStart'
--
-- @
-- The UNTIL rule part defines a DATE or DATE-TIME value that bounds
-- the recurrence rule in an inclusive manner.
-- @
--
-- @
-- If the "DTSTART" property
-- is specified as a date with UTC time or a date with local time and time
-- zone reference, then the UNTIL rule part MUST be specified as a date
-- with UTC time.
-- @
--
-- So a zoned 'DateTimeStart' is bounded by an 'Until' in UTC, while the
-- occurrences are generated as local times in that same time zone.  The two
-- have to be brought into the same time zone before they can be compared,
-- otherwise the comparison is out by that zone's offset from UTC: east of UTC
-- the last instance is dropped, and west of it an instance past the bound is
-- kept.
--
-- We move the 'Until' rather than the occurrences because
-- 'recurRecurrenceRuleDateTimeStarts' is given a bare 'Time.LocalTime' and has
-- no time zone to resolve with, and because unresolving one bound is cheaper
-- than resolving every occurrence.
-- | Whether a local time exists in the time zone that a 'DateTimeStart' names
--
-- @
-- Recurrence rules may generate recurrence instances with an invalid
-- date (e.g., February 30) or nonexistent local time (e.g., 1:30 AM
-- on a day where the local time is moved forward by an hour at 1:00
-- AM).  Such recurrence instances MUST be ignored and MUST NOT be
-- counted as part of the recurrence set.
-- @
--
-- An hour that a transition skips has no instant that maps to it, so resolving
-- a local time inside it lands on an instant belonging to a different local
-- time.  Resolving and unresolving is therefore the test: a local time exists
-- exactly when that round trip gives it back.
--
-- That round trip needs a time zone, so it only judges a zoned start.  For
-- anything else it says yes and leaves the occurrences alone.  A leap second is
-- judged either way, because it needs no time zone to rule out.
localTimeExists :: DateTimeStart -> R (Time.LocalTime -> Bool)
localTimeExists = \case
  DateTimeStartDateTime (DateTimeZoned tzid _) -> do
    ctxMap <- ask
    pure $ case M.lookup tzid ctxMap of
      Nothing -> not . isLeapSecond
      Just (resolutionCtx, unresolutionCtx) -> \localTime ->
        not (isLeapSecond localTime)
          && case tryToResolveLocalTime' resolutionCtx localTime of
            Nothing -> True
            Just utcTime -> tryToUnresolveUTCTime' unresolutionCtx utcTime == Just localTime
  _ -> pure (not . isLeapSecond)

-- | Whether a local time names a leap second
--
-- @
-- The BYSECOND rule part specifies a COMMA-separated list of seconds
-- within a minute.  Valid values are 0 to 60.
-- @
--
-- So a rule may ask for second 60, and 'bySecondExpand' puts it into a
-- 'Time.TimeOfDay' as it stands.  Dividing an instant into a wall clock never
-- produces one, though: whether such a local time survives being resolved and
-- unresolved depends on the time of day and on the offset, so honouring it
-- would make the recurrence set depend on facts about neither the rule nor the
-- calendar.
--
-- A leap second is therefore treated as a local time that does not exist, which
-- is the same answer whatever DTSTART's value type is.  The cost is that
-- BYSECOND=60 never generates an instance.  That is the honest outcome: real
-- leap seconds are announced for particular dates, and nothing here knows which.
isLeapSecond :: Time.LocalTime -> Bool
isLeapSecond = (>= 60) . Time.todSec . Time.localTimeOfDay

-- | Drop the instances that fall after a UTC 'Until'
--
-- @
-- The UNTIL rule part defines a DATE or DATE-TIME value that bounds
-- the recurrence rule in an inclusive manner.
-- @
--
-- The bound is an instant, so this is a question about instants.  Comparing
-- local times, as 'recurRecurrenceRuleLocalTimes' has to, only answers it while
-- the instance and the bound share an offset from UTC; across a transition the
-- two orders disagree.  'localiseUntil' gets the whole-day-and-more cases right
-- and cheaply, so it stays as a pre-filter, and this settles the hour or so
-- around a transition where it cannot.
--
-- An instance whose local time we cannot resolve is kept, so that this only
-- ever removes instances it is sure about.
boundByUntil :: DateTimeStart -> RecurrenceRule -> Set DateTimeStart -> R (Set DateTimeStart)
boundByUntil start recurrenceRule starts = case (start, recurrenceRuleUntilCount recurrenceRule) of
  (DateTimeStartDateTime (DateTimeZoned tzid _), Just (Left (UntilDateTimeUTC untilTime))) -> do
    ctxMap <- ask
    pure $ case M.lookup tzid ctxMap of
      Nothing -> starts
      Just (resolutionCtx, _) -> flip S.filter starts $ \case
        DateTimeStartDateTime (DateTimeZoned _ localTime) ->
          case tryToResolveLocalTime' resolutionCtx localTime of
            Nothing -> True
            Just utcTime -> utcTime <= untilTime
        _ -> True
  _ -> pure starts

-- If the time zone is unknown we leave the 'Until' alone rather than failing.
-- Computing the recurrence set of a zoned event never needed the time zone
-- before, so requiring it here would turn calendars that refer to a time zone
-- they do not define from recurring into an unfixable error.
localiseUntil :: DateTimeStart -> RecurrenceRule -> R RecurrenceRule
localiseUntil start recurrenceRule = case (start, recurrenceRuleUntilCount recurrenceRule) of
  (DateTimeStartDateTime (DateTimeZoned tzid _), Just (Left (UntilDateTimeUTC utcTime))) -> do
    ctxMap <- ask
    let mLocalTime = do
          (_, unresolutionCtx) <- M.lookup tzid ctxMap
          tryToUnresolveUTCTime' unresolutionCtx utcTime
    pure $ case mLocalTime of
      Nothing -> recurrenceRule
      Just localTime ->
        -- A day of slack, because this is only a pre-filter and must not cut
        -- off an instance that 'boundByUntil' would have kept.  An instance
        -- can look later than the bound in local terms while still being at or
        -- before it in instants, by as much as the difference between two of
        -- the zone's offsets from UTC, which is well under a day.
        let slackLocalTime = Time.addLocalTime Time.nominalDay localTime
         in recurrenceRule {recurrenceRuleUntilCount = Just (Left (UntilDateTimeFloating slackLocalTime))}
  _ -> pure recurrenceRule

-- | Compute the occurrences that the recurrence date times imply
--
-- These are enumerated by the calendar rather than generated from a rule, so
-- there are finitely many of them and there is no limit to bound them by.  See
-- 'expandRecurrence'.
recurRecurrenceDateTimes ::
  (Ord component) =>
  component ->
  DateTimeStart ->
  Maybe (Either RecurrenceEnd Duration) ->
  Set RecurrenceDateTimes ->
  R (Set (Occurrence component))
recurRecurrenceDateTimes component dateTimeStart endOrDuration recurrenceDateTimess =
  fmap (S.unions . map S.fromList) $
    forM (S.toList recurrenceDateTimess) $
      let withNewStart newStart = do
            resolvedEndOrDuration <- resolveEndOrDurationDate dateTimeStart endOrDuration newStart
            pure $
              Occurrence
                { occurrenceComponent = component,
                  occurrenceStart = Just newStart,
                  occurrenceEnd = resolvedEndOrDuration
                }
       in \case
            RecurrenceDates dates ->
              mapM
                (withNewStart . DateTimeStartDate)
                (S.toList dates)
            RecurrenceDateTimes dateTimes ->
              mapM
                (withNewStart . DateTimeStartDateTime)
                (S.toList (DateTimes.toSet dateTimes))
            RecurrencePeriods periods ->
              pure $
                map
                  ( \case
                      PeriodStartEnd start end ->
                        Occurrence
                          { occurrenceComponent = component,
                            occurrenceStart = Just $ DateTimeStartDateTime (DateTimeUTC start),
                            occurrenceEnd = Just (Left (RecurrenceEndDateTime (DateTimeUTC end)))
                          }
                      PeriodStartDuration start duration ->
                        Occurrence
                          { occurrenceComponent = component,
                            occurrenceStart = Just $ DateTimeStartDateTime (DateTimeUTC start),
                            occurrenceEnd = Just (Right duration)
                          }
                  )
                  (S.toList periods)

